import 'package:flutter/material.dart';

class NotifyTile extends StatelessWidget {
  const NotifyTile({super.key, required this.on, required this.onChanged});

  final bool on;
  final ValueChanged<bool> onChanged;

  @override
  Widget build(BuildContext context) {
    return ListTile(
      title: const Text('Notifications'),
      // A Material switch on every platform, iPhone included
      trailing: Switch(value: on, onChanged: onChanged),
    );
  }
}

import 'package:flutter/material.dart';

class NotifyTile extends StatelessWidget {
  const NotifyTile({super.key, required this.on, required this.onChanged});

  final bool on;
  final ValueChanged<bool> onChanged;

  @override
  Widget build(BuildContext context) {
    return ListTile(
      title: const Text('Notifications'),
      // iOS and macOS: a Cupertino-style switch. Still painted by Flutter
      trailing: Switch.adaptive(value: on, onChanged: onChanged),
    );
  }
}

