import 'package:flutter/foundation.dart';
import 'package:flutter/material.dart';

// 'native-map' must be registered by your Android and iOS host code
class NativeMap extends StatelessWidget {
  const NativeMap({super.key});

  @override
  Widget build(BuildContext context) {
    return switch (defaultTargetPlatform) {
      TargetPlatform.android => const AndroidView(viewType: 'native-map'),
      TargetPlatform.iOS => const UiKitView(viewType: 'native-map'),
      _ => const Center(child: Text('Map not available here')),
    };
  }
}
